"use strict";

let WaveState = null;
let initialized = false;

let g_DeathActive = false;
let g_DeathRemain = 0;
let g_DeathTicking = false;

let g_SelectedShop1Ability = "";

function StartDeathTimer(seconds) {
    // seconds 必须是 >= 1 的整数，否则直接不启动
    const s = Math.max(0, Math.floor(seconds));
    g_DeathRemain = s;

    const row = $("#DeathRow");
    if (row) row.RemoveClass("Hidden");

    // 立即刷新一次文本
    const label = $("#DeathTimerLabel");
    if (label) label.text = $.Localize("#Revive") + g_DeathRemain + "s";

    // 确保只有一条循环在跑
    if (!g_DeathTicking) {
        g_DeathTicking = true;
        TickDeathTimer();
    }
}

function TickDeathTimer() {
    // 循环唯一出口：不激活就停止并释放 ticking 锁
    if (!g_DeathActive) {
        g_DeathTicking = false;
        return;
    }

    // 每秒递减一次
    g_DeathRemain -= 1;

    if (g_DeathRemain <= 0) {
        const row = $("#DeathRow");
        if (row) row.AddClass("Hidden");
        g_DeathActive = false;
        g_DeathTicking = false;
        return;
    }

    const label = $("#DeathTimerLabel");
    if (label) label.text = $.Localize("#Revive") + g_DeathRemain + "s";

    $.Schedule(1.0, TickDeathTimer);
}


function OnHeroFakeDeath(event) {
    
    const localHero = Players.GetPlayerHeroEntityIndex(Players.GetLocalPlayer());

    if (event.entindex !== localHero)
        return;

    const row = $("#DeathRow");
    if (!row) return;

    if (event.is_dead === 1) {
        const dur = 10;
        const seconds = isFinite(dur) ? Math.ceil(dur) : 0;

        g_DeathActive = true;

        // duration 为 0 的情况：仍显示但用 1 秒兜底，避免“显示后立刻不走”
        StartDeathTimer(seconds > 0 ? seconds : 1);
    } else {
        g_DeathActive = false;
        g_DeathRemain = 0;
        row.AddClass("Hidden");
        // ticking 锁不强行改，TickDeathTimer 下一轮会自动释放
    }
}

function OnShop1DummySelection(event) {
    const row = $("#Shop1DummyRow");
    const icon = $("#Shop1DummyAbilityIcon");
    if (!row || !icon) return;

    const abilityName = event && event.ability ? event.ability : "";
    if (!abilityName) {
        row.AddClass("Hidden");
        icon.abilityname = "";
        icon.ClearPanelEvent("onmouseover");
        icon.ClearPanelEvent("onmouseout");
        g_SelectedShop1Ability = "";
        return;
    }

    g_SelectedShop1Ability = abilityName;
    row.RemoveClass("Hidden");
    icon.abilityname = abilityName;

    icon.ClearPanelEvent("onmouseover");
    icon.ClearPanelEvent("onmouseout");
    icon.SetPanelEvent("onmouseover", function () {
        $.DispatchEvent("DOTAShowAbilityTooltip", icon, abilityName);
    });
    icon.SetPanelEvent("onmouseout", function () {
        $.DispatchEvent("DOTAHideAbilityTooltip", icon);
    });
}

(function () {

    GameEvents.Subscribe("hero_fake_death", OnHeroFakeDeath);
    GameEvents.Subscribe("shop1_dummy_selection", OnShop1DummySelection);

