        if (key === "state") {
            WaveState = data;

            // 第一次收到数据 → 显示整个 UI
            if (!initialized) {

                $("#TopBarContainer").RemoveClass("Hidden");
                $("#TopBarContainer").AddClass("Visible");

                $("#TopBarContent").RemoveClass("Hidden");
                $("#TopBarContent").AddClass("Visible");

                $("#WaveRow").RemoveClass("Hidden");
                $("#WaveRow").AddClass("Visible");

                initialized = true;
            }
        }
    });


    function Update() {
        if (WaveState) {

            const now = Game.GetGameTime();

            /* 第一行：Next / Alive / Boss */
            const nextRemain = Math.max(WaveState.next_wave_time - now, 0);
            $("#NextLabel").text = $.Localize("#Next") + Math.ceil(nextRemain) + "s";

            const expansionProgress = WaveState.expansion_progress || 0;
            const expansionGoal = WaveState.expansion_goal || 5;
            $("#AliveLabel").text = $.Localize("#ExpansionProgress");

            // ------- 进度条更新 ---------
            let pct = expansionGoal > 0 ? (expansionProgress / expansionGoal) : 0;
            if (pct < 0) pct = 0;
            if (pct > 1) pct = 1;

            const bar = $("#AliveBarFill");
            bar.style.width = (pct * 100) + "%";

            let color = "#FFFFFF";      // 安全：白色

            if (pct >= 0.40 && pct < 0.70) color = "#E7BA01";      // 黄色
            else if (pct >= 0.70 && pct < 0.85) color = "#FF7F00"; // 橙色
            else if (pct >= 0.85 && pct <= 1.00) color = "#FF3F3F"; // 红色
            else if (pct > 1.0) color = "#A60000";                 // 深红（超过上限）

            bar.style.backgroundColor = color;
            $("#AliveBarText").text = expansionProgress + " / " + expansionGoal;

            const bossRemain = Math.max(WaveState.next_boss_time - now, 0);
            $("#BossLabel").text = $.Localize("#Boss") + Math.ceil(bossRemain) + "s";

            /* 第二行：Start 或 Wave */
            const preRemain = Math.max(WaveState.pre_delay_end_time - now, 0);

            if (preRemain > 0) {
                $("#StartLabel").visible = true;
                $("#WaveLabel").visible = false;
                $("#StartLabel").text = $.Localize("#Start") + Math.ceil(preRemain) + "s";
            } else {
                $("#StartLabel").visible = false;
                $("#WaveLabel").visible = true;
                $("#WaveLabel").text = $.Localize("#Wave") + (WaveState.current_wave || 0);
            }
        }

        $.Schedule(0.1, Update);
    }

    Update();

    const barContainer = $("#AliveBarContainer");
    if (barContainer) {
        barContainer.SetPanelEvent("onmouseover", function () {
            const progress = WaveState ? (WaveState.expansion_progress || 0) : 0;
            const goal = WaveState ? (WaveState.expansion_goal || 5) : 5;
            const tip = $.Localize("#ExpansionProgressTooltip_1") + " " + (goal - progress) + " " + $.Localize("#ExpansionProgressTooltip_2");
            $.DispatchEvent("DOTAShowTextTooltip", barContainer, tip);
        });
        barContainer.SetPanelEvent("onmouseout", function () {
            $.DispatchEvent("DOTAHideTextTooltip", barContainer);
        });
    }

})();


(function () {
